import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import toast from 'react-hot-toast';
import SignatureCanvas from 'react-signature-canvas';
import { API } from '../context/AuthContext';
import { Document, Page, pdfjs } from 'react-pdf';
import 'react-pdf/dist/Page/AnnotationLayer.css';
import 'react-pdf/dist/Page/TextLayer.css';

pdfjs.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.mjs`;

const FONTS = [
  { name: 'Dancing Script', label: 'Dancing Script', preview: 'Signature' },
  { name: 'Great Vibes', label: 'Great Vibes', preview: 'Signature' },
  { name: 'Pacifico', label: 'Pacifico', preview: 'Signature' },
  { name: 'Pinyon Script', label: 'Pinyon Script', preview: 'Signature' },
];

const DEFAULT_PAGE_WIDTH = 820;

export default function SignPage() {
  const { docId, token } = useParams();

  const [info, setInfo] = useState(null);
  const [loading, setLoading] = useState(true);
  const [step, setStep] = useState('preview');
  const [sigMode, setSigMode] = useState('type');
  const [sigText, setSigText] = useState('');
  const [sigFont, setSigFont] = useState(FONTS[0].name);
  const [submitting, setSubmitting] = useState(false);
  const [pdfPageCount, setPdfPageCount] = useState(1);
  const [pdfWidth, setPdfWidth] = useState(DEFAULT_PAGE_WIDTH);

  const sigCanvasRef = useRef(null);
  const pdfContainerRef = useRef(null);

  const loadPdfPageCount = useCallback(async () => {
    try {
      const res = await axios.get(`${API}/sign/${docId}/${token}/page-count`);

      if (res.data?.pages) {
        setPdfPageCount(Number(res.data.pages));
      }
    } catch (err) {
      console.error(
        'PDF page count load failed:',
        err.response?.data || err.message
      );
      setPdfPageCount(1);
    }
  }, [docId, token]);

  useEffect(() => {
    loadPdfPageCount();

    axios
      .get(`${API}/sign/${docId}/${token}`)
      .then((res) => {
        setInfo(res.data);

        if (res.data.status === 'signed') {
          setStep('done');
        } else {
          setSigText(res.data.recipient_name || '');
        }
      })
      .catch(() => toast.error('Invalid or expired link'))
      .finally(() => setLoading(false));
  }, [docId, token, loadPdfPageCount]);

  const signerLocations = Array.isArray(info?.sign_locations)
    ? info.sign_locations.filter((loc) =>
        !loc.recipientEmail || loc.recipientEmail === info?.recipient_email
      )
    : [];
  const pdfFile = `${API}/documents/${docId}/preview`;

  const updatePdfWidth = useCallback(() => {
    const container = pdfContainerRef.current;

    if (!container) return;

    const nextWidth = Math.max(
      320,
      Math.min(DEFAULT_PAGE_WIDTH, container.clientWidth - 24)
    );

    setPdfWidth(nextWidth);
  }, []);

  useEffect(() => {
    updatePdfWidth();
    window.addEventListener('resize', updatePdfWidth);

    return () => window.removeEventListener('resize', updatePdfWidth);
  }, [updatePdfWidth]);

  const handleSubmit = async () => {
    if (sigMode === 'type' && !sigText.trim()) {
      toast.error('Please enter your signature');
      return;
    }

    if (sigMode === 'draw' && sigCanvasRef.current?.isEmpty()) {
      toast.error('Please draw your signature');
      return;
    }

    setSubmitting(true);

    try {
      const payload = {
        signature_text: sigText,
        signature_font: sigFont,
        signature_image:
          sigMode === 'draw' ? sigCanvasRef.current.toDataURL() : '',
      };

      await axios.post(`${API}/sign/${docId}/${token}`, payload);

      setStep('done');
      toast.success('Document signed successfully!');
    } catch (err) {
      toast.error(err.response?.data?.error || 'Signing failed');
    } finally {
      setSubmitting(false);
    }
  };

  const handleDownload = async () => {
    try {
      const res = await axios.get(`${API}/sign/${docId}/${token}/download`);
      window.open(res.data.pdf_url, '_blank');
    } catch {
      toast.error('Download failed');
    }
  };

  if (loading) {
    return (
      <div className="loader-full" style={{ background: 'var(--bg)' }}>
        <div className="spinner" />
      </div>
    );
  }

  if (!info) {
    return (
      <div className="loader-full" style={{ flexDirection: 'column', gap: 16 }}>
        <div style={{ fontSize: 48 }}>❌</div>
        <h2>Invalid or expired link</h2>
        <p style={{ color: 'var(--text2)' }}>
          This signing link is no longer valid.
        </p>
      </div>
    );
  }

  return (
    <div
      style={{
        minHeight: '100vh',
        background: 'var(--bg)',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      <div
        style={{
          background: 'var(--bg2)',
          borderBottom: '1px solid var(--border)',
          padding: '16px 32px',
          display: 'flex',
          alignItems: 'center',
          gap: 12,
        }}
      >
        <div
          style={{
            width: 36,
            height: 36,
            borderRadius: 10,
            background: 'linear-gradient(135deg,var(--primary),var(--accent))',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: 18,
          }}
        >
          ✍
        </div>

        <div>
          <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: 18 }}>
            Sign Prime
          </div>
        </div>
      </div>

      <div style={{ flex: 1, display: 'flex', gap: 0 }}>
        <div style={{ flex: 1, padding: 32, overflowY: 'auto' }}>
          <div style={{ marginBottom: 20 }}>
            <h2 style={{ fontSize: 22, marginBottom: 4 }}>{info.title}</h2>

            {info.message && (
              <div
                style={{
                  background: 'var(--surface)',
                  border: '1px solid var(--border)',
                  borderLeft: '4px solid var(--primary)',
                  borderRadius: 8,
                  padding: '12px 16px',
                  fontSize: 13,
                  color: 'var(--text2)',
                  fontStyle: 'italic',
                  marginBottom: 16,
                }}
              >
                "{info.message}"
              </div>
            )}

            <p style={{ fontSize: 13, color: 'var(--text2)' }}>
              Signing as:{' '}
              <strong style={{ color: 'var(--text)' }}>
                {info.recipient_name || info.recipient_email}
              </strong>
            </p>
          </div>

          <div
            ref={pdfContainerRef}
            style={{
              background: 'var(--surface)',
              borderRadius: 12,
              overflowY: 'auto',
              overflowX: 'hidden',
              border: '1px solid var(--border)',
              position: 'relative',
              height: 700,
            }}
          >
            <div
              style={{
                position: 'relative',
                width: '100%',
                background: '#f8fafc',
                padding: '12px 0',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                gap: 18,
              }}
            >
              <Document
                file={pdfFile}
                loading={
                  <div style={{ padding: 30, color: 'var(--text2)' }}>
                    Loading PDF...
                  </div>
                }
                onLoadSuccess={({ numPages }) => {
                  setPdfPageCount(numPages || 1);
                  setTimeout(updatePdfWidth, 0);
                }}
                onLoadError={(err) => {
                  console.error('PDF load failed:', err);
                  toast.error('Failed to load PDF preview');
                }}
              >
                {Array.from({ length: pdfPageCount }, (_, index) => {
                  const pageNumber = index + 1;

                  return (
                    <div
                      key={pageNumber}
                      style={{
                        position: 'relative',
                        width: pdfWidth,
                        background: '#fff',
                        boxShadow: '0 8px 24px rgba(15,23,42,0.18)',
                      }}
                    >
                      <Page
                        pageNumber={pageNumber}
                        width={pdfWidth}
                        renderAnnotationLayer={false}
                        renderTextLayer={false}
                      />

                      {step === 'sign' &&
                        signerLocations
                          .filter((loc) => Number(loc.page || 1) === pageNumber)
                          .map((loc, i) => {
                            const isDateTime = loc.type === 'datetime';

                            return (
                              <div
                                key={`${pageNumber}-${i}`}
                                style={{
                                  position: 'absolute',
                                  left: `${loc.x}%`,
                                  top: `${loc.y}%`,
                                  width: loc.width || 160,
                                  height: loc.height || 48,
                                  background: isDateTime
                                    ? 'rgba(16,185,129,0.15)'
                                    : 'rgba(99,102,241,0.15)',
                                  border: isDateTime
                                    ? '2px dashed var(--success)'
                                    : '2px dashed var(--primary)',
                                  borderRadius: 6,
                                  display: 'flex',
                                  alignItems: 'center',
                                  justifyContent: 'center',
                                  fontFamily: isDateTime
                                    ? 'Inter'
                                    : sigMode === 'type'
                                    ? sigFont
                                    : 'inherit',
                                  fontSize: isDateTime ? 13 : 20,
                                  color: isDateTime
                                    ? 'var(--success)'
                                    : 'var(--primary)',
                                  textAlign: 'center',
                                  padding: '0 8px',
                                  zIndex: 10,
                                }}
                              >
                                {isDateTime
                                  ? new Date().toLocaleString()
                                  : sigMode === 'type' && sigText
                                  ? sigText
                                  : '✍ Sign here'}
                              </div>
                            );
                          })}
                    </div>
                  );
                })}
              </Document>
            </div>
          </div>
        </div>

        <div
          style={{
            width: 380,
            background: 'var(--bg2)',
            borderLeft: '1px solid var(--border)',
            padding: 28,
            display: 'flex',
            flexDirection: 'column',
            gap: 20,
          }}
        >
          {step === 'done' ? (
            <div style={{ textAlign: 'center', padding: '40px 0' }}>
              <div style={{ fontSize: 64, marginBottom: 16 }}>✅</div>

              <h2 style={{ marginBottom: 8 }}>Document Signed!</h2>

              <p
                style={{
                  color: 'var(--text2)',
                  fontSize: 14,
                  marginBottom: 28,
                }}
              >
                You have successfully signed "{info.title}"
              </p>

              <button
                className="btn btn-primary btn-lg"
                onClick={handleDownload}
                style={{ width: '100%', justifyContent: 'center' }}
              >
                ⬇ Download Signed Document
              </button>

              <p style={{ fontSize: 12, color: 'var(--text3)', marginTop: 16 }}>
                You can close this window
              </p>
            </div>
          ) : step === 'preview' ? (
            <>
              <div>
                <h3 style={{ marginBottom: 6 }}>Review Document</h3>
                <p style={{ fontSize: 13, color: 'var(--text2)' }}>
                  Please review the document on the left before signing.
                </p>
              </div>

              <div className="card">
                <div
                  style={{
                    fontSize: 13,
                    color: 'var(--text2)',
                    lineHeight: 2,
                  }}
                >
                  <div>
                    📄{' '}
                    <strong style={{ color: 'var(--text)' }}>
                      {info.title}
                    </strong>
                  </div>

                  <div>
                    ✍{' '}
                    <strong style={{ color: 'var(--text)' }}>
                      {signerLocations.length || 0}
                    </strong>{' '}
                    assigned field(s)
                  </div>

                  <div>
                    👤 Signing as:{' '}
                    <strong style={{ color: 'var(--text)' }}>
                      {info.recipient_email}
                    </strong>
                  </div>
                </div>
              </div>

              {signerLocations.length === 0 ? (
                <div
                  style={{
                    padding: 14,
                    borderRadius: 10,
                    background: 'rgba(239,68,68,0.12)',
                    border: '1px solid rgba(239,68,68,0.25)',
                    color: 'var(--text2)',
                    fontSize: 13,
                    lineHeight: 1.5,
                  }}
                >
                  No fields are assigned to this signer. Ask the sender to assign fields first.
                </div>
              ) : (
                <button
                  className="btn btn-primary btn-lg"
                  onClick={() => setStep('sign')}
                  style={{ justifyContent: 'center' }}
                >
                  → Proceed to Sign
                </button>
              )}
            </>
          ) : (
            <>
              <div>
                <h3 style={{ marginBottom: 4 }}>Create Your Signature</h3>
                <p style={{ fontSize: 12, color: 'var(--text3)' }}>
                  This will be applied only to signature field(s). Date and time
                  will be added automatically.
                </p>
              </div>

              <div className="tabs">
                <div
                  className={`tab ${sigMode === 'type' ? 'active' : ''}`}
                  onClick={() => setSigMode('type')}
                >
                  Type
                </div>

                <div
                  className={`tab ${sigMode === 'draw' ? 'active' : ''}`}
                  onClick={() => setSigMode('draw')}
                >
                  Draw
                </div>
              </div>

              {sigMode === 'type' ? (
                <>
                  <div>
                    <label className="label">Your Name</label>
                    <input
                      className="input"
                      value={sigText}
                      onChange={(e) => setSigText(e.target.value)}
                      placeholder="Type your full name"
                    />
                  </div>

                  <div>
                    <label className="label">Signature Style</label>

                    <div
                      style={{
                        display: 'flex',
                        flexDirection: 'column',
                        gap: 8,
                      }}
                    >
                      {FONTS.map((f) => (
                        <div
                          key={f.name}
                          className={`sig-font-option ${
                            sigFont === f.name ? 'selected' : ''
                          }`}
                          onClick={() => setSigFont(f.name)}
                        >
                          <div
                            style={{
                              fontFamily: f.name,
                              fontSize: 28,
                              color:
                                sigFont === f.name
                                  ? 'var(--primary-light)'
                                  : 'var(--text)',
                              marginBottom: 2,
                            }}
                          >
                            {sigText || 'Your Signature'}
                          </div>

                          <div
                            style={{
                              fontSize: 10,
                              color: 'var(--text3)',
                              fontFamily: 'Inter',
                            }}
                          >
                            {f.label}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                </>
              ) : (
                <div>
                  <label className="label">Draw Your Signature</label>

                  <div className="sig-canvas-wrap">
                    <SignatureCanvas
                      ref={sigCanvasRef}
                      canvasProps={{
                        width: 320,
                        height: 120,
                        className: 'sig-canvas',
                      }}
                      penColor="#1e1e48"
                    />
                  </div>

                  <button
                    className="btn btn-ghost btn-sm"
                    style={{ marginTop: 8 }}
                    onClick={() => sigCanvasRef.current?.clear()}
                  >
                    Clear
                  </button>
                </div>
              )}

              <div
                style={{
                  background: 'white',
                  borderRadius: 10,
                  padding: '16px 20px',
                  minHeight: 60,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                {sigMode === 'type' ? (
                  <span
                    style={{
                      fontFamily: sigFont,
                      fontSize: 30,
                      color: '#1a1a3e',
                    }}
                  >
                    {sigText || 'Preview'}
                  </span>
                ) : (
                  <span style={{ color: '#94a3b8', fontSize: 13 }}>
                    Preview shows in draw area above
                  </span>
                )}
              </div>

              <div style={{ display: 'flex', gap: 10 }}>
                <button
                  className="btn btn-ghost btn-sm"
                  onClick={() => setStep('preview')}
                >
                  ← Back
                </button>

                <button
                  className="btn btn-primary"
                  style={{ flex: 1, justifyContent: 'center' }}
                  onClick={handleSubmit}
                  disabled={submitting}
                >
                  {submitting ? 'Signing...' : '✍ Sign Document'}
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
