import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { formatDistanceToNow } from 'date-fns';
import toast from 'react-hot-toast';
import Layout from '../components/Layout';
import api from '../api/axios';

function StatusBadge({ status }) {
  return <span className={`badge badge-${status}`}>{status}</span>;
}

export default function DashboardPage() {
  const [docs, setDocs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const navigate = useNavigate();

const [theme, setTheme] = useState(() => {
  return localStorage.getItem('theme') || 'dark';
});

useEffect(() => {
  document.documentElement.setAttribute('data-theme', theme);
  localStorage.setItem('theme', theme);
}, [theme]);

const toggleTheme = () => {
  setTheme((prevTheme) => (prevTheme === 'dark' ? 'light' : 'dark'));
};

  const load = async () => {
    try {
      setLoading(true);

      const res = await api.get('/documents');

      setDocs(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      console.error('Failed to load documents:', err.response?.data || err.message);
      toast.error(err.response?.data?.error || 'Failed to load documents');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const handleDelete = async (e, docId) => {
    e.stopPropagation();

    if (!window.confirm('Delete this document? This cannot be undone.')) return;

    try {
      await api.delete(`/documents/${docId}`);

      toast.success('Document deleted');
      setDocs((prevDocs) => prevDocs.filter((d) => d.id !== docId));
    } catch (err) {
      console.error('Failed to delete:', err.response?.data || err.message);
      toast.error(err.response?.data?.error || 'Failed to delete');
    }
  };

  const filtered = filter === 'all' ? docs : docs.filter((d) => d.status === filter);

  const stats = {
    total: docs.length,
    pending: docs.filter((d) => ['sent', 'partial'].includes(d.status)).length,
    completed: docs.filter((d) => d.status === 'completed').length,
    draft: docs.filter((d) => d.status === 'draft').length,
  };

  return (
    <Layout>
      <div
        className="page-header"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <div>
          <h1 className="page-title">Documents</h1>
          <p className="page-subtitle">Manage and track all your signature requests</p>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
  <button
    className="theme-toggle-btn"
    onClick={toggleTheme}
    title="Toggle theme"
  >
    {theme === 'dark' ? '☀️ Light' : '🌙 Dark'}
  </button>

  <button className="btn btn-primary" onClick={() => navigate('/upload')}>
    + New Document
  </button>
</div>
      </div>

      <div className="page-body">
        {/* Stats */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit,minmax(220px,1fr))',
            gap: 20,
            marginBottom: 36,
          }}
        >
          {[
            {
              label: 'Total Documents',
              value: stats.total,
              color: '#6366f1',
              icon: '📄',
            },
            {
              label: 'Pending',
              value: stats.pending,
              color: '#f59e0b',
              icon: '⏳',
            },
            {
              label: 'Completed',
              value: stats.completed,
              color: '#10b981',
              icon: '✅',
            },
            {
              label: 'Drafts',
              value: stats.draft,
              color: '#94a3b8',
              icon: '📝',
            },
          ].map((s) => (
            <div
              key={s.label}
              className="card"
              style={{
                position: 'relative',
                overflow: 'hidden',
                padding: '24px',
                borderRadius: 22,
                background:
                  'linear-gradient(145deg, rgba(20,20,45,0.95), rgba(32,18,60,0.95))',
                border: '1px solid rgba(255,255,255,0.06)',
                boxShadow: `0 0 25px ${s.color}20`,
                transition: 'all 0.25s ease',
              }}
            >
              <div
                style={{
                  position: 'absolute',
                  top: -30,
                  right: -30,
                  width: 100,
                  height: 100,
                  background: `${s.color}20`,
                  borderRadius: '50%',
                  filter: 'blur(30px)',
                }}
              />

              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  marginBottom: 18,
                }}
              >
                <div
                  style={{
                    width: 52,
                    height: 52,
                    borderRadius: 16,
                    background: `${s.color}15`,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: 24,
                    border: `1px solid ${s.color}40`,
                  }}
                >
                  {s.icon}
                </div>

                <div
                  style={{
                    fontSize: 42,
                    fontWeight: 800,
                    color: s.color,
                    lineHeight: 1,
                    fontFamily: 'Space Grotesk, sans-serif',
                  }}
                >
                  {s.value}
                </div>
              </div>

              <div
                style={{
                  fontSize: 15,
                  fontWeight: 700,
                  color: '#fff',
                  marginBottom: 4,
                }}
              >
                {s.label}
              </div>
            </div>
          ))}
        </div>

        {/* Filter tabs */}
        <div style={{ width: '100%', marginBottom: 28 }}>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(5, 1fr)',
              gap: 12,
              width: '100%',
              background: 'rgba(255,255,255,0.03)',
              padding: 12,
              borderRadius: 22,
              border: '1px solid rgba(255,255,255,0.06)',
              backdropFilter: 'blur(10px)',
            }}
          >
            {[
              { key: 'all', label: 'All Documents', icon: '📂' },
              { key: 'draft', label: 'Drafts', icon: '📝' },
              { key: 'sent', label: 'Sent', icon: '📤' },
              { key: 'partial', label: 'Partial', icon: '⏳' },
              { key: 'completed', label: 'Completed', icon: '✅' },
            ].map((f) => {
              const active = filter === f.key;

              return (
                <button
                  key={f.key}
                  onClick={() => setFilter(f.key)}
                  style={{
                    border: 'none',
                    outline: 'none',
                    cursor: 'pointer',
                    borderRadius: 18,
                    padding: '18px 16px',
                    transition: 'all 0.25s ease',
                    background: active
                      ? 'linear-gradient(135deg,#6366f1,#8b5cf6)'
                      : 'rgba(255,255,255,0.03)',
                    color: active ? '#fff' : 'var(--text2)',
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: 8,
                    minHeight: 90,
                    boxShadow: active ? '0 0 25px rgba(99,102,241,0.35)' : 'none',
                  }}
                >
                  <span style={{ fontSize: 22 }}>{f.icon}</span>

                  <span
                    style={{
                      fontSize: 14,
                      fontWeight: active ? 700 : 600,
                      fontFamily: 'Inter',
                      letterSpacing: '0.3px',
                    }}
                  >
                    {f.label}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        {/* Document list */}
        {loading ? (
          <div style={{ textAlign: 'center', padding: 60 }}>
            <div className="spinner" style={{ margin: '0 auto' }} />
          </div>
        ) : filtered.length === 0 ? (
          <div
            style={{
              textAlign: 'center',
              padding: '80px 20px',
              color: 'var(--text2)',
            }}
          >
            <div style={{ fontSize: 64, marginBottom: 16 }}>📄</div>
            <h3 style={{ marginBottom: 8 }}>No documents yet</h3>
            <p style={{ fontSize: 14 }}>Upload your first PDF to get started</p>

            <button
              className="btn btn-primary"
              style={{ marginTop: 24 }}
              onClick={() => navigate('/upload')}
            >
              Upload Document
            </button>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {filtered.map((doc) => {
              const signed =
                doc.recipients?.filter((r) => r.status === 'signed').length || 0;

              const total = doc.recipients?.length || 0;

              const createdAt = doc.created_at?._seconds
                ? formatDistanceToNow(new Date(doc.created_at._seconds * 1000), {
                    addSuffix: true,
                  })
                : 'recently';

              return (
                <div
                  key={doc.id}
                  className="doc-card"
                  onClick={() => navigate(`/documents/${doc.id}`)}
                >
                  <div
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: 16,
                    }}
                  >
                    <div
                      style={{
                        width: 44,
                        height: 44,
                        borderRadius: 12,
                        background:
                          'linear-gradient(135deg,rgba(99,102,241,0.2),rgba(168,85,247,0.2))',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontSize: 20,
                        flexShrink: 0,
                      }}
                    >
                      📄
                    </div>

                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: 10,
                          marginBottom: 4,
                        }}
                      >
                        <span
                          style={{
                            fontWeight: 600,
                            fontSize: 15,
                            color: 'var(--text)',
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap',
                          }}
                        >
                          {doc.title}
                        </span>

                        <StatusBadge status={doc.status} />
                      </div>

                      <div
                        style={{
                          display: 'flex',
                          gap: 16,
                          fontSize: 12,
                          color: 'var(--text3)',
                          flexWrap: 'wrap',
                        }}
                      >
                        <span>👥 {signed}/{total} signed</span>
                        <span>🕐 {createdAt}</span>

                        {doc.recipients?.slice(0, 3).map((r) => (
                          <span
                            key={r.email}
                            style={{
                              color:
                                r.status === 'signed'
                                  ? 'var(--success)'
                                  : 'var(--text3)',
                            }}
                          >
                            {r.status === 'signed' ? '✓' : '○'}{' '}
                            {r.email.split('@')[0]}
                          </span>
                        ))}
                      </div>
                    </div>

                    <div
                      style={{ display: 'flex', gap: 8 }}
                      onClick={(e) => e.stopPropagation()}
                    >
                      <button
                        className="btn btn-secondary btn-sm"
                        onClick={() => navigate(`/documents/${doc.id}`)}
                      >
                        View
                      </button>

                      <button
                        className="btn btn-danger btn-sm"
                        onClick={(e) => handleDelete(e, doc.id)}
                      >
                        Delete
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </Layout>
  );
}